/**
 * TypeSpec source code parser.
 *
 * Parses TypeSpec source text and extracts entity structure (fields, decorators, types).
 * Regex-based MVP parser — handles the subset of TypeSpec generated by our generator,
 * plus: model inheritance (extends), spread (...Model), standalone enums, custom scalars,
 * unions, aliases, namespaces, operations, interfaces, discriminator, default values,
 * never type, internal modifier, const, using, import.
 *
 * Pure function — no side effects, no I/O.
 */

import { DATA_TYPE_HIERARCHY } from "@/lib/data-types";
import {
  CLASSIFICATION_EXTENSION_KEY,
  PIN_EXTENSION_KEY,
  TAGS_EXTENSION_KEY,
  classificationFromEnterpriseMember,
  parseExtensionArguments,
  parseStringTuple,
  setOwn,
  unescapeTypeSpecString,
} from "./governance-decorators";

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export interface ParsedTypeSpecDecorators {
  doc?: string;
  format?: string;
  secret?: boolean;
  minLength?: number;
  maxLength?: number;
  minValue?: number;
  maxValue?: number;
  minValueExclusive?: number;
  maxValueExclusive?: number;
  pattern?: string;
  deprecated?: string;
  encode?: string;
  encodeSubType?: string;
  /** Legacy: a field `@tag(...)` — `@tag("classification:PII")` was the pre-16.6 classification form. */
  tag?: string;
  /**
   * Classification as the app's level, from `@Enterprise.dataClassification(...)` (member mapped back) or the
   * `x-classification` extension (Story 16.6). The legacy `@tag` form stays in `tag`.
   */
  classification?: string;
  /** A reference field's version pin, from the `x-super-schema-pin` extension (never a generic extension). */
  referencedEntityVersion?: string;
  summary?: string;
  minItems?: number;
  maxItems?: number;
  visibility?: string[];
  discriminator?: string;
  extensions?: Record<string, unknown>;
  error?: boolean;
  example?: string;
  encodedName?: { mimeType: string; name: string };
  friendlyName?: string;
}

export interface ParsedTypeSpecField {
  name: string;
  type: string;
  isOptional: boolean;
  isKey: boolean;
  decorators: ParsedTypeSpecDecorators;
  arrayElementType?: string;
  /** Real-compiler reader only: the type is `T | null` (T is `type` / `arrayElementType`), as opposed to `isOptional` (`?`). */
  nullableType?: boolean;
  /**
   * Real-compiler reader only: the type is a union (or an array of one: `arrayElementType` is "union") with these members, `null` aside.
   * `unionName` is the declared union's name, absent for an inline `A | B`.
   */
  unionName?: string;
  unionMembers?: string[];
  defaultValue?: string;
  isNever?: boolean;
  isInternal?: boolean;
}

export interface ParsedTypeSpecModel {
  name: string;
  doc?: string;
  fields: ParsedTypeSpecField[];
  extends?: string;
  spreadFrom?: string[];
  discriminator?: string;
  isError?: boolean;
  friendlyName?: string;
  tags?: string[];
  /** Generic vendor extensions above the model (x-tags / x-classification excluded), JSON-shaped values. */
  extensions?: Record<string, unknown>;
}

export interface ParsedTypeSpecEnum {
  name: string;
  doc?: string;
  values: string[];
}

export interface ParsedTypeSpecScalar {
  name: string;
  doc?: string;
  baseType: string;
  format?: string;
  pattern?: string;
}

export interface ParsedTypeSpecUnion {
  name: string;
  doc?: string;
  memberTypes: string[];
}

export interface ParsedTypeSpecAlias {
  name: string;
  type: string;
}

export interface ParsedTypeSpecDecoratorDefinition {
  name: string;
  doc?: string;
  signature: string;
  targetTypes: string[];
}

export interface ParsedTypeSpecOperationParam {
  name: string;
  type: string;
  location?: "path" | "query" | "header" | "body";
  isOptional: boolean;
}

export interface ParsedTypeSpecOperation {
  name: string;
  doc?: string;
  httpMethod?: string;
  httpPath?: string;
  params: ParsedTypeSpecOperationParam[];
  returnType: string;
}

export interface ParsedTypeSpecInterface {
  name: string;
  doc?: string;
  operations: ParsedTypeSpecOperation[];
}

export interface ParsedTypeSpecConst {
  name: string;
  type?: string;
  value: string;
}

export interface ParsedTypeSpecDocument {
  namespace?: string;
  usings: string[];
  imports: string[];
  models: ParsedTypeSpecModel[];
  enums: ParsedTypeSpecEnum[];
  scalars: ParsedTypeSpecScalar[];
  unions: ParsedTypeSpecUnion[];
  aliases: ParsedTypeSpecAlias[];
  decorators: ParsedTypeSpecDecoratorDefinition[];
  operations: ParsedTypeSpecOperation[];
  interfaces: ParsedTypeSpecInterface[];
  consts: ParsedTypeSpecConst[];
}

// ---------------------------------------------------------------------------
// TypeSpec scalar -> our type system mapping
// ---------------------------------------------------------------------------

const TYPESPEC_SCALAR_TO_TYPE: Record<string, string> = {};

for (const dt of DATA_TYPE_HIERARCHY) {
  // Map typespecScalar -> id  (e.g. "int32" -> "int32", "Record" -> "map")
  TYPESPEC_SCALAR_TO_TYPE[dt.typespecScalar] = dt.id;
  // Also map the id directly in case it's used as-is
  TYPESPEC_SCALAR_TO_TYPE[dt.id] = dt.id;
}

// Additional common aliases that might appear in pasted TypeSpec
TYPESPEC_SCALAR_TO_TYPE["Record"] = "map";
TYPESPEC_SCALAR_TO_TYPE["model"] = "object";
TYPESPEC_SCALAR_TO_TYPE["void"] = "string";
TYPESPEC_SCALAR_TO_TYPE["never"] = "never";

/**
 * Map a TypeSpec type expression to our internal type ID.
 */
export function mapTypeSpecType(typeExpr: string): { type: string; arrayElementType?: string } {
  const trimmed = typeExpr.trim();

  // Array type: "string[]" or "int32[]"; the element may be a qualified model name ("Billing.Payments.Address[]"), kept as written
  const arrayMatch = trimmed.match(/^(\w+(?:\.\w+)*)\[\]$/);
  if (arrayMatch) {
    const elementType = TYPESPEC_SCALAR_TO_TYPE[arrayMatch[1]] ?? arrayMatch[1];
    return { type: "array", arrayElementType: elementType };
  }

  // Record type: "Record<string>" or "Record<string, int32>"
  const recordMatch = trimmed.match(/^Record<(.+)>$/);
  if (recordMatch) {
    return { type: "map" };
  }

  // Union type inline: "Type1 | Type2"
  if (trimmed.includes("|")) {
    return { type: trimmed };
  }

  // Simple scalar
  const mapped = TYPESPEC_SCALAR_TO_TYPE[trimmed];
  if (mapped) {
    return { type: mapped };
  }

  // Unknown type — return as-is (could be a model reference)
  return { type: trimmed };
}

// ---------------------------------------------------------------------------
// Full document parser
// ---------------------------------------------------------------------------

/**
 * Parse a full TypeSpec document containing multiple constructs.
 * Returns all parsed constructs: models, enums, scalars, unions, aliases,
 * operations, interfaces, namespace, using/import statements.
 */
export function parseTypeSpecDocument(source: string): ParsedTypeSpecDocument {
  const result: ParsedTypeSpecDocument = {
    usings: [],
    imports: [],
    models: [],
    enums: [],
    scalars: [],
    unions: [],
    aliases: [],
    decorators: [],
    operations: [],
    interfaces: [],
    consts: [],
  };

  if (!source || typeof source !== "string") return result;

  const lines = source.split("\n");
  let i = 0;

  while (i < lines.length) {
    const line = lines[i].trim();

    // Skip empty lines and line comments
    if (line === "" || line.startsWith("//")) {
      i++;
      continue;
    }

    // Block comments
    if (line.startsWith("/*")) {
      while (i < lines.length && !lines[i].includes("*/")) {
        i++;
      }
      i++;
      continue;
    }

    // import statement
    const importMatch = line.match(/^import\s+"(.+)"\s*;?\s*$/);
    if (importMatch) {
      result.imports.push(importMatch[1]);
      i++;
      continue;
    }

    // using statement
    const usingMatch = line.match(/^using\s+(.+?)\s*;?\s*$/);
    if (usingMatch) {
      result.usings.push(usingMatch[1]);
      i++;
      continue;
    }

    // namespace
    const nsMatch = line.match(/^namespace\s+([\w.]+)\s*\{?\s*$/);
    if (nsMatch) {
      result.namespace = nsMatch[1];
      // If the namespace has a brace, we continue parsing inside it
      // (we treat the rest of the file as inside this namespace)
      i++;
      continue;
    }
    // namespace without braces (just declaration)
    const nsMatchSemicolon = line.match(/^namespace\s+([\w.]+)\s*;\s*$/);
    if (nsMatchSemicolon) {
      result.namespace = nsMatchSemicolon[1];
      i++;
      continue;
    }

    // const declaration
    const constMatch = line.match(/^const\s+(\w+)\s*(?::\s*(\w+))?\s*=\s*(.+?)\s*;?\s*$/);
    if (constMatch) {
      result.consts.push({
        name: constMatch[1],
        type: constMatch[2] || undefined,
        value: constMatch[3],
      });
      i++;
      continue;
    }

    // alias declaration
    const aliasMatch = line.match(/^alias\s+(\w+)\s*=\s*(.+?)\s*;\s*$/);
    if (aliasMatch) {
      result.aliases.push({
        name: aliasMatch[1],
        type: aliasMatch[2].trim(),
      });
      i++;
      continue;
    }

    // decorator declaration
    const decoratorMatch = line.match(/^(?:extern\s+)?dec\s+(\w+)\s*\((.*?)\)\s*;?\s*$/);
    if (decoratorMatch) {
      const doc = collectPrecedingDoc(lines, i);
      const signature = decoratorMatch[2].trim();
      result.decorators.push({
        name: decoratorMatch[1],
        doc: doc || undefined,
        signature,
        targetTypes: extractDecoratorTargetTypes(signature),
      });
      i++;
      continue;
    }

    // scalar declaration: `scalar Name extends BaseType;`
    const scalarMatch = line.match(/^scalar\s+(\w+)\s+extends\s+(\w+)\s*;?\s*$/);
    if (scalarMatch) {
      const decorators = collectPrecedingDecorators(lines, i);
      result.scalars.push({
        name: scalarMatch[1],
        doc: decorators.doc,
        baseType: scalarMatch[2],
        format: decorators.format,
        pattern: decorators.pattern,
      });
      i++;
      continue;
    }

    // union declaration: `union Name { ... }` or `union Name = Type1 | Type2;`
    const unionInlineMatch = line.match(/^union\s+(\w+)\s*=\s*(.+?)\s*;\s*$/);
    if (unionInlineMatch) {
      const doc = collectPrecedingDoc(lines, i);
      result.unions.push({
        name: unionInlineMatch[1],
        doc: doc || undefined,
        memberTypes: unionInlineMatch[2].split("|").map((t) => t.trim()).filter(Boolean),
      });
      i++;
      continue;
    }

    const unionBlockMatch = line.match(/^union\s+(\w+)\s*\{?\s*$/);
    if (unionBlockMatch) {
      const doc = collectPrecedingDoc(lines, i);
      const { body, endIdx } = extractBlock(lines, i);
      const memberTypes = body
        .map((l) => l.trim())
        .filter((l) => l && !l.startsWith("//") && !l.startsWith("@"))
        .map((l) => l.replace(/[,;]$/, "").trim())
        .filter(Boolean);
      result.unions.push({
        name: unionBlockMatch[1],
        doc: doc || undefined,
        memberTypes,
      });
      i = endIdx + 1;
      continue;
    }

    // enum declaration
    const enumMatch = line.match(/^enum\s+(\w+)\s*\{?\s*$/);
    if (enumMatch) {
      const doc = collectPrecedingDoc(lines, i);
      const { body, endIdx } = extractBlock(lines, i);
      const values = body
        .map((l) => l.trim())
        .filter((l) => l && !l.startsWith("//") && !l.startsWith("@"))
        .map((l) => l.replace(/[,;]$/, "").trim())
        // Handle `Value: "string_value"` syntax; a member may itself be quoted (`"in-progress"`)
        .map((l) => leadingMemberName(l))
        .filter(Boolean);
      result.enums.push({
        name: enumMatch[1],
        doc: doc || undefined,
        values,
      });
      i = endIdx + 1;
      continue;
    }

    // interface declaration
    const ifaceMatch = line.match(/^interface\s+(\w+)\s*\{?\s*$/);
    if (ifaceMatch) {
      const doc = collectPrecedingDoc(lines, i);
      const { body, endIdx } = extractBlock(lines, i);
      const operations = parseOperationsFromBody(body);
      result.interfaces.push({
        name: ifaceMatch[1],
        doc: doc || undefined,
        operations,
      });
      i = endIdx + 1;
      continue;
    }

    // standalone op declaration: `op name(...): ReturnType;`
    const opMatch = line.match(/^op\s+(\w+)\s*\((.*)?\)\s*:\s*(.+?)\s*;\s*$/);
    if (opMatch) {
      const doc = collectPrecedingDoc(lines, i);
      const { httpMethod, httpPath } = extractHttpDecorators(lines, i);
      const params = parseOperationParams(opMatch[2] || "");
      result.operations.push({
        name: opMatch[1],
        doc: doc || undefined,
        httpMethod,
        httpPath,
        params,
        returnType: opMatch[3].trim(),
      });
      i++;
      continue;
    }

    // model declaration (with optional extends)
    // Must have { on this line or a subsequent line
    const modelMatch = line.match(/^model\s+(\w+)\s*(?:extends\s+(\w+)\s*)?\{?\s*$/);
    if (modelMatch) {
      // Check that there's actually a block body (has opening brace)
      const hasOpenBrace = line.includes("{") ||
        (i + 1 < lines.length && lines[i + 1].trim().startsWith("{"));
      if (!hasOpenBrace) {
        i++;
        continue;
      }

      const doc = collectPrecedingDoc(lines, i);
      const discriminator = collectDiscriminator(lines, i);
      const isError = collectModelIsError(lines, i);
      const friendlyName = collectModelFriendlyName(lines, i);
      const tags = collectModelTags(lines, i);
      const extensions = collectModelExtensions(lines, i);
      const { body, endIdx } = extractBlock(lines, i);
      const { fields, spreadFrom } = parseModelBody(body);

      result.models.push({
        name: modelMatch[1],
        doc: doc || undefined,
        fields,
        extends: modelMatch[2] || undefined,
        spreadFrom: spreadFrom.length > 0 ? spreadFrom : undefined,
        discriminator: discriminator || undefined,
        isError: isError || undefined,
        friendlyName: friendlyName || undefined,
        tags: tags.length > 0 ? tags : undefined,
        extensions,
      });
      i = endIdx + 1;
      continue;
    }

    // Decorators before a construct — skip and let the construct handler read them
    if (line.startsWith("@") || line.startsWith("#")) {
      i++;
      continue;
    }

    // Closing brace from namespace
    if (line === "}") {
      i++;
      continue;
    }

    // Unrecognized line — skip
    i++;
  }

  return result;
}

// ---------------------------------------------------------------------------
// Single model parser (backwards-compatible)
// ---------------------------------------------------------------------------

/**
 * Parse TypeSpec source text and extract a model definition with fields.
 *
 * Returns null if the input cannot be parsed (no model block found, or
 * syntactically broken beyond what the regex parser can handle).
 */
export function parseTypeSpec(source: string): ParsedTypeSpecModel | null {
  if (!source || typeof source !== "string") return null;

  const doc = parseTypeSpecDocument(source);
  if (doc.models.length === 0) return null;

  return doc.models[0];
}

// ---------------------------------------------------------------------------
// Block extraction utilities
// ---------------------------------------------------------------------------

function extractBlock(lines: string[], startIdx: number): { body: string[]; endIdx: number } {
  let braceDepth = 0;
  let endIdx = startIdx;
  let foundOpenBrace = false;

  for (let i = startIdx; i < lines.length; i++) {
    const line = lines[i];
    for (const ch of line) {
      if (ch === "{") {
        braceDepth++;
        foundOpenBrace = true;
      }
      if (ch === "}") {
        braceDepth--;
        if (foundOpenBrace && braceDepth === 0) {
          endIdx = i;
          return { body: lines.slice(startIdx + 1, endIdx), endIdx };
        }
      }
    }
  }

  // If no closing brace found, return everything until end
  return { body: lines.slice(startIdx + 1), endIdx: lines.length - 1 };
}

function collectPrecedingDoc(lines: string[], idx: number): string | undefined {
  return collectPrecedingDecorators(lines, idx).doc;
}

function collectPrecedingDecorators(
  lines: string[],
  idx: number
): ParsedTypeSpecDecorators {
  const decorators: ParsedTypeSpecDecorators = {};

  for (let i = idx - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (line === "") continue;

    if (!line.startsWith("@") && !line.startsWith("#")) break;

    const parsed = parseDecoratorLine(line);
    if (!parsed?.decorators) continue;

    if (parsed.decorators.extensions) {
      decorators.extensions = decorators.extensions
        ? {
            ...parsed.decorators.extensions,
            ...decorators.extensions,
          }
        : parsed.decorators.extensions;
    }

    for (const [key, value] of Object.entries(parsed.decorators)) {
      if (key === "extensions") continue;
      if ((decorators as Record<string, unknown>)[key] === undefined) {
        (decorators as Record<string, unknown>)[key] = value;
      }
    }
  }

  return decorators;
}

function collectDiscriminator(lines: string[], idx: number): string | undefined {
  for (let i = idx - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (line === "") continue;
    const discMatch = line.match(/^@discriminator\("(.+)"\)$/);
    if (discMatch) {
      return discMatch[1];
    }
    if (!line.startsWith("@") && !line.startsWith("#")) break;
  }
  return undefined;
}

/** Optional `TypeSpec.` / `OpenAPI.` qualifier in front of `extension`. */
const EXTENSION_DECORATOR = String.raw`@(?:TypeSpec\.)?(?:OpenAPI\.)?extension`;

/** `@TypeSpec.OpenAPI.extension("x-tags", #[...])` (qualified or bare) → the tuple text. */
const TAGS_EXTENSION_LINE = new RegExp(
  String.raw`^${EXTENSION_DECORATOR}\("${TAGS_EXTENSION_KEY}"\s*,\s*(#\[.*\])\)$`
);

/** `@TypeSpec.OpenAPI.extension("x-classification", "LEVEL")` (qualified or bare) → the escaped level. */
const CLASSIFICATION_EXTENSION_LINE = new RegExp(
  String.raw`^${EXTENSION_DECORATOR}\("${CLASSIFICATION_EXTENSION_KEY}"\s*,\s*"((?:[^"\\]|\\.)*)"\)$`
);

/** `@TypeSpec.OpenAPI.extension("x-super-schema-pin", "1.2")` (qualified or bare) → the escaped version. */
const PIN_EXTENSION_LINE = new RegExp(
  String.raw`^${EXTENSION_DECORATOR}\("${PIN_EXTENSION_KEY}"\s*,\s*"((?:[^"\\]|\\.)*)"\)$`
);

/** Bare, JsonSchema- or OpenAPI-qualified `extension` decorator call; group 1 is the argument text. */
const GENERIC_EXTENSION_LINE = /^@(?:TypeSpec\.)?(?:(?:JsonSchema|OpenAPI)\.)?extension\((.*)\)$/;

/**
 * A generic vendor-extension decorator line → `{key, value}` (value in its JSON shape). Undefined for other
 * lines, partial lines, and the keys with a dedicated path (`x-tags`, `x-classification`).
 */
function parseGenericExtensionLine(line: string): { key: string; value: unknown } | undefined {
  const m = line.match(GENERIC_EXTENSION_LINE);
  if (!m) return undefined;
  const args = parseExtensionArguments(m[1]);
  if (!args || args.key === TAGS_EXTENSION_KEY || args.key === CLASSIFICATION_EXTENSION_KEY) return undefined;
  return args;
}

/** Model-level generic extensions above the model (JsonSchema + OpenAPI pair collapses per key), or undefined. */
function collectModelExtensions(lines: string[], idx: number): Record<string, unknown> | undefined {
  const found: { key: string; value: unknown }[] = [];
  for (let i = idx - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (line === "") continue;
    if (!line.startsWith("@") && !line.startsWith("#")) break;
    const ext = parseGenericExtensionLine(line);
    if (ext) found.unshift(ext);
  }
  if (found.length === 0) return undefined;
  const out: Record<string, unknown> = {};
  for (const { key, value } of found) setOwn(out, key, value);
  return out;
}

/** Model tags in source order: the `x-tags` extension (Story 16.6) and legacy model-level `@tag("...")`. */
function collectModelTags(lines: string[], idx: number): string[] {
  const tags: string[] = [];
  for (let i = idx - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (line === "") continue;
    if (!line.startsWith("@") && !line.startsWith("#")) break;
    const tagMatch = line.match(/^@tag\("(.*)"\)$/);
    if (tagMatch) {
      tags.unshift(tagMatch[1]);
      continue;
    }
    const extMatch = line.match(TAGS_EXTENSION_LINE);
    const values = extMatch ? parseStringTuple(extMatch[1]) : undefined;
    if (values) tags.unshift(...values);
  }
  return tags;
}

function collectModelIsError(lines: string[], idx: number): boolean {
  for (let i = idx - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (line === "") continue;
    if (line === "@error") return true;
    if (!line.startsWith("@") && !line.startsWith("#")) break;
  }
  return false;
}

function collectModelFriendlyName(lines: string[], idx: number): string | undefined {
  for (let i = idx - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (line === "") continue;
    const match = line.match(/^@friendlyName\("(.*)"\)$/);
    if (match) return match[1];
    if (!line.startsWith("@") && !line.startsWith("#")) break;
  }
  return undefined;
}

function extractHttpDecorators(lines: string[], idx: number): { httpMethod?: string; httpPath?: string } {
  let httpMethod: string | undefined;
  let httpPath: string | undefined;

  for (let i = idx - 1; i >= 0; i--) {
    const line = lines[i].trim();
    if (line === "") continue;
    if (!line.startsWith("@") && !line.startsWith("#")) break;

    // @route("/path")
    const routeMatch = line.match(/^@route\("(.+)"\)$/);
    if (routeMatch) httpPath = routeMatch[1];

    // @get, @post, @put, @delete, @patch
    const methodMatch = line.match(/^@(get|post|put|delete|patch)$/);
    if (methodMatch) httpMethod = methodMatch[1].toUpperCase();
  }

  return { httpMethod, httpPath };
}

// ---------------------------------------------------------------------------
// Model body parsing (fields + spread)
// ---------------------------------------------------------------------------

function parseModelBody(bodyLines: string[]): { fields: ParsedTypeSpecField[]; spreadFrom: string[] } {
  const fields: ParsedTypeSpecField[] = [];
  const spreadFrom: string[] = [];

  let pendingDecorators: ParsedTypeSpecDecorators = {};
  let pendingIsKey = false;
  let pendingIsInternal = false;

  for (const rawLine of bodyLines) {
    let line = rawLine.trim();

    // Skip empty lines and comments
    if (line === "" || line.startsWith("//")) {
      continue;
    }

    while (line.startsWith("@") || line.startsWith("#")) {
      const split = splitLeadingDecorator(line);
      const decoratorLine = split?.decorator ?? line;
      const parsed = parseDecoratorLine(decoratorLine);
      if (parsed) {
        if (parsed.isKey) {
          pendingIsKey = true;
        } else {
          // Merge extensions specially to avoid overwriting
          if (parsed.decorators?.extensions && pendingDecorators.extensions) {
            parsed.decorators.extensions = { ...pendingDecorators.extensions, ...parsed.decorators.extensions };
          }
          Object.assign(pendingDecorators, parsed.decorators);
        }
      }
      if (decoratorLine === "@internal") {
        pendingIsInternal = true;
      }

      line = split?.rest.trim() ?? "";
      if (!line) break;
    }

    if (!line) {
      continue;
    }

    // Spread syntax: `...ModelName;`
    const spreadMatch = line.match(/^\.\.\.\s*(\w+)\s*;?\s*$/);
    if (spreadMatch) {
      spreadFrom.push(spreadMatch[1]);
      continue;
    }

    // Field declaration: `name: type;` or `name?: type;` or `name: type = defaultValue;`
    // (`name` may be a backticked identifier: `` `in-progress`: string; ``)
    const fieldMatch = line.match(/^(\w+|`(?:[^`\\]|\\.)*`)(\?)?\s*:\s*(.+?)(?:\s*=\s*(.+?))?\s*;\s*$/);
    if (fieldMatch) {
      const fieldName = fieldMatch[1].startsWith("`") ? leadingMemberName(fieldMatch[1]) : fieldMatch[1];
      const isOptional = fieldMatch[2] === "?";
      const typeExpr = fieldMatch[3].trim();
      const defaultValue = fieldMatch[4]?.trim();

      // Skip `never` type fields
      if (typeExpr === "never") {
        pendingDecorators = {};
        pendingIsKey = false;
        pendingIsInternal = false;
        continue;
      }

      const { type, arrayElementType } = mapTypeSpecType(typeExpr);

      const field: ParsedTypeSpecField = {
        name: fieldName,
        type,
        isOptional,
        isKey: pendingIsKey,
        decorators: { ...pendingDecorators },
      };

      if (arrayElementType) {
        field.arrayElementType = arrayElementType;
      }

      if (defaultValue !== undefined) {
        field.defaultValue = defaultValue;
      }

      if (pendingIsInternal) {
        field.isInternal = true;
      }

      fields.push(field);

      // Reset pending state
      pendingDecorators = {};
      pendingIsKey = false;
      pendingIsInternal = false;
      continue;
    }
  }

  return { fields, spreadFrom };
}

function splitLeadingDecorator(line: string): { decorator: string; rest: string } | null {
  if (!line.startsWith("@") && !line.startsWith("#")) return null;

  for (let i = 1; i < line.length; i++) {
    if (line[i] !== " ") continue;

    const decorator = line.slice(0, i).trim();
    if (decorator === "@internal" || parseDecoratorLine(decorator)) {
      return {
        decorator,
        rest: line.slice(i + 1),
      };
    }
  }

  return {
    decorator: line,
    rest: "",
  };
}

// ---------------------------------------------------------------------------
// Operation parsing
// ---------------------------------------------------------------------------

function parseOperationsFromBody(bodyLines: string[]): ParsedTypeSpecOperation[] {
  const ops: ParsedTypeSpecOperation[] = [];
  let pendingDoc: string | undefined;
  let pendingHttpMethod: string | undefined;
  let pendingHttpPath: string | undefined;

  for (let i = 0; i < bodyLines.length; i++) {
    const line = bodyLines[i].trim();

    if (line === "" || line.startsWith("//")) continue;

    // Decorator
    if (line.startsWith("@") || line.startsWith("#")) {
      const docMatch = line.match(/^@doc\("(.*)"\)$/);
      if (docMatch) pendingDoc = unescapeString(docMatch[1]);

      const routeMatch = line.match(/^@route\("(.+)"\)$/);
      if (routeMatch) pendingHttpPath = routeMatch[1];

      const methodMatch = line.match(/^@(get|post|put|delete|patch)$/);
      if (methodMatch) pendingHttpMethod = methodMatch[1].toUpperCase();
      continue;
    }

    // op declaration inside interface
    const opMatch = line.match(/^op\s+(\w+)\s*\((.*)?\)\s*:\s*(.+?)\s*;\s*$/);
    if (opMatch) {
      const params = parseOperationParams(opMatch[2] || "");
      ops.push({
        name: opMatch[1],
        doc: pendingDoc,
        httpMethod: pendingHttpMethod,
        httpPath: pendingHttpPath,
        params,
        returnType: opMatch[3].trim(),
      });
      pendingDoc = undefined;
      pendingHttpMethod = undefined;
      pendingHttpPath = undefined;
      continue;
    }

    // Inline op without `op` keyword: `name(...): ReturnType;`
    const inlineOpMatch = line.match(/^(\w+)\s*\((.*)?\)\s*:\s*(.+?)\s*;\s*$/);
    if (inlineOpMatch) {
      const params = parseOperationParams(inlineOpMatch[2] || "");
      ops.push({
        name: inlineOpMatch[1],
        doc: pendingDoc,
        httpMethod: pendingHttpMethod,
        httpPath: pendingHttpPath,
        params,
        returnType: inlineOpMatch[3].trim(),
      });
      pendingDoc = undefined;
      pendingHttpMethod = undefined;
      pendingHttpPath = undefined;
    }
  }

  return ops;
}

function parseOperationParams(paramStr: string): ParsedTypeSpecOperationParam[] {
  if (!paramStr.trim()) return [];

  const params: ParsedTypeSpecOperationParam[] = [];
  // Split by comma, handling potential nested generics
  const parts = splitParams(paramStr);

  for (const part of parts) {
    const trimmed = part.trim();
    if (!trimmed) continue;

    // Check for location decorators: @path, @query, @header, @body
    let location: "path" | "query" | "header" | "body" | undefined;
    let cleanPart = trimmed;

    const locMatch = cleanPart.match(/^@(path|query|header|body)\s+/);
    if (locMatch) {
      location = locMatch[1] as "path" | "query" | "header" | "body";
      cleanPart = cleanPart.substring(locMatch[0].length);
    }

    // Parse `name?: type` or `name: type`
    const paramMatch = cleanPart.match(/^(\w+)(\?)?\s*:\s*(.+)$/);
    if (paramMatch) {
      params.push({
        name: paramMatch[1],
        type: paramMatch[3].trim(),
        location,
        isOptional: paramMatch[2] === "?",
      });
    }
  }

  return params;
}

function extractDecoratorTargetTypes(signature: string): string[] {
  const [firstParam] = splitParams(signature);
  if (!firstParam) return [];

  const colonIndex = firstParam.indexOf(":");
  if (colonIndex === -1) return [];

  return firstParam
    .slice(colonIndex + 1)
    .split("|")
    .map((part) => part.trim())
    .filter(Boolean);
}

function splitParams(str: string): string[] {
  const parts: string[] = [];
  let depth = 0;
  let current = "";

  for (const ch of str) {
    if (ch === "<" || ch === "(") depth++;
    if (ch === ">" || ch === ")") depth--;
    if (ch === "," && depth === 0) {
      parts.push(current);
      current = "";
    } else {
      current += ch;
    }
  }
  if (current.trim()) parts.push(current);
  return parts;
}

// ---------------------------------------------------------------------------
// Decorator parsing
// ---------------------------------------------------------------------------

interface DecoratorParseResult {
  isKey?: boolean;
  decorators?: ParsedTypeSpecDecorators;
}

function parseDecoratorLine(line: string): DecoratorParseResult | null {
  // @key
  if (line === "@key") {
    return { isKey: true };
  }

  // @secret
  if (line === "@secret") {
    return { decorators: { secret: true } };
  }

  // @discriminator("fieldName")
  const discMatch = line.match(/^@discriminator\("(.+)"\)$/);
  if (discMatch) {
    return { decorators: { discriminator: discMatch[1] } };
  }

  // @doc("...")
  const docMatch = line.match(/^@doc\("(.*)"\)$/);
  if (docMatch) {
    return { decorators: { doc: unescapeString(docMatch[1]) } };
  }

  // @summary("...")
  const summaryMatch = line.match(/^@summary\("(.*)"\)$/);
  if (summaryMatch) {
    return { decorators: { summary: unescapeString(summaryMatch[1]) } };
  }

  // @format("...")
  const formatMatch = line.match(/^@format\("(.*)"\)$/);
  if (formatMatch) {
    return { decorators: { format: formatMatch[1] } };
  }

  // @pattern("...")
  const patternMatch = line.match(/^@pattern\("(.*)"\)$/);
  if (patternMatch) {
    return { decorators: { pattern: unescapeString(patternMatch[1]) } };
  }

  // @encode("...") or @encode("...", "...") or @encode("...", bareType)
  const encodeMatch = line.match(/^@encode\("([^"]*)"(?:\s*,\s*(?:"([^"]*)"|(\w+)))?\)$/);
  if (encodeMatch) {
    const result: ParsedTypeSpecDecorators = { encode: encodeMatch[1] };
    const subType = encodeMatch[2] || encodeMatch[3];
    if (subType) {
      result.encodeSubType = subType;
    }
    return { decorators: result };
  }

  // @minLength(N)
  const minLengthMatch = line.match(/^@minLength\((\d+)\)$/);
  if (minLengthMatch) {
    return { decorators: { minLength: parseInt(minLengthMatch[1], 10) } };
  }

  // @maxLength(N)
  const maxLengthMatch = line.match(/^@maxLength\((\d+)\)$/);
  if (maxLengthMatch) {
    return { decorators: { maxLength: parseInt(maxLengthMatch[1], 10) } };
  }

  // @minValue(N)
  const minValueMatch = line.match(/^@minValue\((-?\d+(?:\.\d+)?)\)$/);
  if (minValueMatch) {
    return { decorators: { minValue: parseFloat(minValueMatch[1]) } };
  }

  // @maxValue(N)
  const maxValueMatch = line.match(/^@maxValue\((-?\d+(?:\.\d+)?)\)$/);
  if (maxValueMatch) {
    return { decorators: { maxValue: parseFloat(maxValueMatch[1]) } };
  }

  // @minValueExclusive(N)
  const minValueExclMatch = line.match(/^@minValueExclusive\((-?\d+(?:\.\d+)?)\)$/);
  if (minValueExclMatch) {
    return { decorators: { minValueExclusive: parseFloat(minValueExclMatch[1]) } };
  }

  // @maxValueExclusive(N)
  const maxValueExclMatch = line.match(/^@maxValueExclusive\((-?\d+(?:\.\d+)?)\)$/);
  if (maxValueExclMatch) {
    return { decorators: { maxValueExclusive: parseFloat(maxValueExclMatch[1]) } };
  }

  // @minItems(N)
  const minItemsMatch = line.match(/^@minItems\((\d+)\)$/);
  if (minItemsMatch) {
    return { decorators: { minItems: parseInt(minItemsMatch[1], 10) } };
  }

  // @maxItems(N)
  const maxItemsMatch = line.match(/^@maxItems\((\d+)\)$/);
  if (maxItemsMatch) {
    return { decorators: { maxItems: parseInt(maxItemsMatch[1], 10) } };
  }

  // @tag("...")
  const tagMatch = line.match(/^@tag\("(.*)"\)$/);
  if (tagMatch) {
    return { decorators: { tag: tagMatch[1] } };
  }

  // #deprecated "..."
  const deprecatedMatch = line.match(/^#deprecated\s+"(.*)"$/);
  if (deprecatedMatch) {
    return { decorators: { deprecated: unescapeString(deprecatedMatch[1]) } };
  }

  // @deprecated("...") — alternate syntax
  const deprecatedAltMatch = line.match(/^@deprecated\("(.*)"\)$/);
  if (deprecatedAltMatch) {
    return { decorators: { deprecated: unescapeString(deprecatedAltMatch[1]) } };
  }

  // @visibility(Lifecycle.Create, Lifecycle.Read, ...)
  const visibilityMatch = line.match(/^@visibility\((.+)\)$/);
  if (visibilityMatch) {
    const phases = visibilityMatch[1]
      .split(",")
      .map((s) => s.trim())
      .map((s) => s.replace(/^Lifecycle\./, ""))
      .filter(Boolean);
    return { decorators: { visibility: phases } };
  }

  // @Enterprise.dataClassification(Enterprise.DataClassification.PII), or unqualified with `using Enterprise;`
  const dataClassificationMatch = line.match(/^@(?:Enterprise\.)?dataClassification\(\s*([\w.]+)\s*\)$/);
  if (dataClassificationMatch) {
    const level = classificationFromEnterpriseMember(dataClassificationMatch[1]);
    return level ? { decorators: { classification: level } } : null;
  }

  // @TypeSpec.OpenAPI.extension("x-classification", "LEVEL") — a level with no Enterprise member
  const classificationExtMatch = line.match(CLASSIFICATION_EXTENSION_LINE);
  if (classificationExtMatch) {
    return { decorators: { classification: unescapeTypeSpecString(classificationExtMatch[1]) } };
  }

  // @TypeSpec.OpenAPI.extension("x-super-schema-pin", "1.2") - a reference's version pin
  const pinMatch = line.match(PIN_EXTENSION_LINE);
  if (pinMatch) {
    const version = unescapeTypeSpecString(pinMatch[1]);
    // An empty value is no pin: it stays an ordinary extension (falls through to the generic reader).
    if (version) return { decorators: { referencedEntityVersion: version } };
  }

  // @extension("key", value) / @TypeSpec.JsonSchema.extension(...) / @TypeSpec.OpenAPI.extension(...)
  const ext = parseGenericExtensionLine(line);
  if (ext) {
    return { decorators: { extensions: { [ext.key]: ext.value } } };
  }

  // @error
  if (line === "@error") {
    return { decorators: { error: true } };
  }

  // @example(#{...}) or @example(...) — store raw literal string
  const exampleMatch = line.match(/^@example\((.*)\)$/);
  if (exampleMatch) {
    return { decorators: { example: exampleMatch[1] } };
  }

  // @encodedName("mimeType", "name")
  const encodedNameMatch = line.match(/^@encodedName\("([^"]+)"\s*,\s*"([^"]+)"\)$/);
  if (encodedNameMatch) {
    return { decorators: { encodedName: { mimeType: encodedNameMatch[1], name: encodedNameMatch[2] } } };
  }

  // @friendlyName("...")
  const friendlyNameMatch = line.match(/^@friendlyName\("(.*)"\)$/);
  if (friendlyNameMatch) {
    return { decorators: { friendlyName: friendlyNameMatch[1] } };
  }

  // Unknown decorator — ignore gracefully
  return null;
}

// ---------------------------------------------------------------------------
// Utilities
// ---------------------------------------------------------------------------

function unescapeString(str: string): string {
  // One pass: `\\n` is a backslash then `n`, not a newline. Handles the escapes TypeSpec defines and the generator
  // writes (`\n \r \t \" \\ \$ \@ \``); any other backslash sequence is kept as written (`\.` in a regex).
  return str.replace(/\\(.)/g, (whole, ch: string) => {
    switch (ch) {
      case "n":
        return "\n";
      case "r":
        return "\r";
      case "t":
        return "\t";
      case '"':
      case "\\":
      case "$":
      case "@":
      case "`":
        return ch;
      default:
        return whole;
    }
  });
}

/**
 * The name at the start of a model property / enum member line: a bare identifier, a backticked identifier or
 * (enum members) a quoted string. Quoted forms are unescaped, so `` `in-progress` `` and `"in-progress"` both
 * yield `in-progress` — what the TypeSpec compiler reports as the member / property name.
 */
const QUOTED_NAME = /^(?:`((?:[^`\\]|\\.)*)`|"((?:[^"\\]|\\.)*)")/;

function leadingMemberName(line: string): string {
  const quoted = QUOTED_NAME.exec(line);
  if (quoted) return unescapeString(quoted[1] ?? quoted[2] ?? "");
  return line.split(":")[0].trim();
}

// ---------------------------------------------------------------------------
// Decorator target validation
// ---------------------------------------------------------------------------

export interface DecoratorWarning {
  decorator: string;
  fieldName: string;
  fieldType: string;
  message: string;
}

const STRING_ONLY_DECORATORS = ["minLength", "maxLength", "pattern", "format"];
const NUMERIC_ONLY_DECORATORS = ["minValue", "maxValue", "minValueExclusive", "maxValueExclusive"];
const ARRAY_ONLY_DECORATORS = ["minItems", "maxItems"];

/**
 * Validate that decorators are applied to appropriate field types.
 * Returns an array of warnings for mismatched decorator/type combinations.
 */
export function validateDecoratorTarget(
  decorators: ParsedTypeSpecDecorators,
  fieldName: string,
  fieldType: string
): DecoratorWarning[] {
  const warnings: DecoratorWarning[] = [];

  const isStringType = ["string", "url"].includes(fieldType);
  const isNumericType = [
    "integer", "int8", "int16", "int32", "int64", "safeint",
    "uint8", "uint16", "uint32", "uint64",
    "numeric", "float", "float32", "float64",
    "decimal", "decimal128",
  ].includes(fieldType);
  const isArrayType = fieldType === "array";

  for (const dec of STRING_ONLY_DECORATORS) {
    if (decorators[dec as keyof ParsedTypeSpecDecorators] != null && !isStringType) {
      warnings.push({
        decorator: `@${dec}`,
        fieldName,
        fieldType,
        message: `@${dec} is intended for string types, but applied to '${fieldType}'`,
      });
    }
  }

  for (const dec of NUMERIC_ONLY_DECORATORS) {
    if (decorators[dec as keyof ParsedTypeSpecDecorators] != null && !isNumericType) {
      warnings.push({
        decorator: `@${dec}`,
        fieldName,
        fieldType,
        message: `@${dec} is intended for numeric types, but applied to '${fieldType}'`,
      });
    }
  }

  for (const dec of ARRAY_ONLY_DECORATORS) {
    if (decorators[dec as keyof ParsedTypeSpecDecorators] != null && !isArrayType) {
      warnings.push({
        decorator: `@${dec}`,
        fieldName,
        fieldType,
        message: `@${dec} is intended for array types, but applied to '${fieldType}'`,
      });
    }
  }

  return warnings;
}

// ---------------------------------------------------------------------------
// Diff computation for apply logic
// ---------------------------------------------------------------------------

export interface TypeSpecFieldDiff {
  toAdd: ParsedTypeSpecField[];
  toUpdate: Array<{ name: string; changes: Partial<ParsedTypeSpecField> }>;
  toRemove: string[];
}

export interface ExistingFieldSummary {
  name: string;
  type: string;
  isOptional: boolean;
  isKey: boolean;
}

/**
 * Compute the diff between parsed TypeSpec fields and existing entity fields.
 */
export function computeFieldDiff(
  parsed: ParsedTypeSpecField[],
  existing: ExistingFieldSummary[]
): TypeSpecFieldDiff {
  const existingMap = new Map<string, ExistingFieldSummary>();
  for (const f of existing) {
    existingMap.set(f.name, f);
  }

  const parsedNames = new Set(parsed.map((f) => f.name));
  const toAdd: ParsedTypeSpecField[] = [];
  const toUpdate: Array<{ name: string; changes: Partial<ParsedTypeSpecField> }> = [];
  const toRemove: string[] = [];

  for (const pf of parsed) {
    const ef = existingMap.get(pf.name);
    if (!ef) {
      // New field
      toAdd.push(pf);
    } else {
      // Check for changes
      const changes: Partial<ParsedTypeSpecField> = {};
      if (pf.type !== ef.type) changes.type = pf.type;
      if (pf.isOptional !== ef.isOptional) changes.isOptional = pf.isOptional;
      if (pf.isKey !== ef.isKey) changes.isKey = pf.isKey;
      // Always include decorators in update so they're synced
      changes.decorators = pf.decorators;

      if (Object.keys(changes).length > 1 || pf.type !== ef.type || pf.isOptional !== ef.isOptional || pf.isKey !== ef.isKey) {
        toUpdate.push({ name: pf.name, changes });
      }
    }
  }

  for (const ef of existing) {
    if (!parsedNames.has(ef.name)) {
      toRemove.push(ef.name);
    }
  }

  return { toAdd, toUpdate, toRemove };
}
